PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?expensePaymentAmount
WHERE {
  SERVICE <mapped> {
    ?claim a ins:Claim ;
           ins:claimNumber ?claimNumber ;
           ins:hasExpensePayment ?expensePayment .
    ?expensePayment ins:expensePaymentAmount ?expensePaymentAmount .
  }
}

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?policyNumber ?policyHolder ?premiumAmountPaid
       ?lossPaymentAmount ?lossReserveAmount ?expensePaymentAmount ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?claim a ins:Claim ;
           ins:claimNumber ?claimNumber ;
           ins:against ?pcd .

    OPTIONAL {
      ?claim ins:hasLossPayment ?lp .
      ?lp ins:lossPaymentAmount ?lossPaymentAmount .
    }

    OPTIONAL {
      ?claim ins:hasLossReserve ?lr .
      ?lr ins:lossReserveAmount ?lossReserveAmount .
    }

    OPTIONAL {
      ?claim ins:hasExpensePayment ?ep .
      ?ep ins:expensePaymentAmount ?expensePaymentAmount .
    }

    OPTIONAL {
      ?claim ins:hasExpenseReserve ?er .
      ?er ins:expenseReserveAmount ?expenseReserveAmount .
    }

    ?pcd ins:hasPolicy ?policy .

    OPTIONAL { ?policy ins:policyNumber ?policyNumber . }

    OPTIONAL {
      ?policy ins:hasPolicyHolder ?ph .
      OPTIONAL { ?ph ins:policyHolderId ?policyHolder . }
    }

    OPTIONAL {
      ?pcd ins:hasPremiumAmount ?premium .
      ?premium ins:premiumAmount ?premiumAmountPaid .
    }
  }
}

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?policyNumber ?numberOfClaims ?averageLoss
WHERE {
  {
    SELECT ?policyNumber (COUNT(DISTINCT ?claim) AS ?numberOfClaims) (AVG(?claimLoss) AS ?averageLoss)
    WHERE {
      SERVICE <mapped> {
        ?claim a ins:Claim ;
               ins:against ?pcd .

        ?pcd ins:hasPolicy ?policy .
        ?policy ins:policyNumber ?policyNumber .

        OPTIONAL {
          SELECT ?claim (SUM(?v) AS ?lossPaymentSum)
          WHERE {
            SERVICE <mapped> {
              ?claim ins:hasLossPayment ?lp .
              ?lp ins:lossPaymentAmount ?v .
            }
          }
          GROUP BY ?claim
        }

        OPTIONAL {
          SELECT ?claim (SUM(?v) AS ?lossReserveSum)
          WHERE {
            SERVICE <mapped> {
              ?claim ins:hasLossReserve ?lr .
              ?lr ins:lossReserveAmount ?v .
            }
          }
          GROUP BY ?claim
        }

        OPTIONAL {
          SELECT ?claim (SUM(?v) AS ?expensePaymentSum)
          WHERE {
            SERVICE <mapped> {
              ?claim ins:hasExpensePayment ?ep .
              ?ep ins:expensePaymentAmount ?v .
            }
          }
          GROUP BY ?claim
        }

        OPTIONAL {
          SELECT ?claim (SUM(?v) AS ?expenseReserveSum)
          WHERE {
            SERVICE <mapped> {
              ?claim ins:hasExpenseReserve ?er .
              ?er ins:expenseReserveAmount ?v .
            }
          }
          GROUP BY ?claim
        }

        BIND(
          COALESCE(?lossPaymentSum, 0) +
          COALESCE(?lossReserveSum, 0) +
          COALESCE(?expensePaymentSum, 0) +
          COALESCE(?expenseReserveSum, 0)
          AS ?claimLoss
        )
      }
    }
    GROUP BY ?policyNumber
  }
}
ORDER BY ?policyNumber

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?lossReserveAmount
WHERE {
  SERVICE <mapped> {
    ?claim a ins:Claim ;
           ins:claimNumber ?claimNumber ;
           ins:hasLossReserve ?lossReserve .
    ?lossReserve ins:lossReserveAmount ?lossReserveAmount .
  }
}

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?agentId ?policyNumber
       (COALESCE(SUM(?lossPaymentAmt), 0) +
        COALESCE(SUM(?lossReserveAmt), 0) +
        COALESCE(SUM(?expensePaymentAmt), 0) +
        COALESCE(SUM(?expenseReserveAmt), 0) AS ?totalLoss)
WHERE {
  SERVICE <mapped> {
    ?agent a ins:Agent ;
           ins:agentId ?agentId .

    ?policy a ins:Policy ;
            ins:soldByAgent ?agent ;
            ins:policyNumber ?policyNumber .

    ?pcd a ins:PolicyCoverageDetail ;
         ins:hasPolicy ?policy .

    ?claim a ins:Claim ;
           ins:against ?pcd .

    OPTIONAL {
      ?claim ins:hasLossPayment ?lp .
      ?lp ins:lossPaymentAmount ?lossPaymentAmt .
    }

    OPTIONAL {
      ?claim ins:hasLossReserve ?lr .
      ?lr ins:lossReserveAmount ?lossReserveAmt .
    }

    OPTIONAL {
      ?claim ins:hasExpensePayment ?ep .
      ?ep ins:expensePaymentAmount ?expensePaymentAmt .
    }

    OPTIONAL {
      ?claim ins:hasExpenseReserve ?er .
      ?er ins:expenseReserveAmount ?expenseReserveAmt .
    }
  }
}
GROUP BY ?agentId ?policyNumber
ORDER BY ?agentId ?policyNumber
